/*
 * variables.css
 * Fuente única de tokens de diseño del proyecto.
 * REGLA: Ningún valor de color, tipografía o espaciado
 * debe aparecer hardcodeado en otro archivo CSS.
 * Proyecto: Productora Web (SCRUM-20)
 */

:root {

  /* === PALETA DE MARCA === */
  --color-brand-primary:       #C8A96E;   /* Dorado — acento principal */
  --color-brand-primary-dark:  #A6854A;   /* Dorado oscuro — hover/active */
  --color-brand-secondary:     #1A1A2E;   /* Azul noche — fondo principal */
  --color-brand-secondary-alt: #16213E;   /* Variante fondo — secciones alternas */
  --color-brand-accent:        #E94560;   /* Rojo/coral — CTA críticos */

  /* === NEUTROS === */
  --color-neutral-white:       #FFFFFF;
  --color-neutral-off-white:   #F4F4F4;   /* Fondos de tarjetas claras */
  --color-neutral-light:       #CCCCCC;   /* Bordes, separadores */
  --color-neutral-mid:         #888888;   /* Texto secundario, placeholders */
  --color-neutral-dark:        #222222;   /* Texto sobre fondos claros */
  --color-neutral-black:       #0D0D0D;   /* Negro profundo — overlays */

  /* === SEMÁNTICOS DE UI === */
  --color-bg-page:             var(--color-brand-secondary);
  --color-bg-section-alt:      var(--color-brand-secondary-alt);
  --color-bg-card:             var(--color-neutral-black);
  --color-text-primary:        var(--color-neutral-off-white);
  --color-text-secondary:      var(--color-neutral-mid);
  --color-text-on-light:       var(--color-neutral-dark);
  --color-border-default:      var(--color-neutral-light);
  --color-focus-ring:          var(--color-brand-accent);
  --color-success:             #2ECC71;
  --color-error:               #E74C3C;
  --color-warning:             #F39C12;

  /* === TIPOGRAFÍA === */
  /* NOTA: Las @font-face o <link> de Google Fonts van en cada HTML,
     no aquí. Estas variables solo declaran los nombres de familia. */

  --font-family-heading:  'Montserrat', 'Arial Black', sans-serif;
  --font-family-body:     'Open Sans', 'Arial', sans-serif;
  --font-family-mono:     'Courier New', Courier, monospace;

  --font-size-xs:    0.75rem;   /*  12px */
  --font-size-sm:    0.875rem;  /*  14px */
  --font-size-base:  1rem;      /*  16px — base del body */
  --font-size-md:    1.125rem;  /*  18px */
  --font-size-lg:    1.5rem;    /*  24px */
  --font-size-xl:    2rem;      /*  32px */
  --font-size-2xl:   2.5rem;    /*  40px */
  --font-size-3xl:   3.5rem;    /*  56px — hero heading */

  --font-weight-regular:   400;
  --font-weight-medium:    500;
  --font-weight-semibold:  600;
  --font-weight-bold:      700;
  --font-weight-black:     900;

  --line-height-tight:    1.2;
  --line-height-snug:     1.4;
  --line-height-normal:   1.6;
  --line-height-relaxed:  1.8;

  --letter-spacing-tight:  -0.02em;
  --letter-spacing-normal:  0em;
  --letter-spacing-wide:    0.05em;
  --letter-spacing-wider:   0.1em;
  --letter-spacing-widest:  0.2em;

  /* === ESPACIADO === */
  /* Escala basada en múltiplos de 4px (base rem 16px) */
  --space-1:    0.25rem;   /*   4px */
  --space-2:    0.5rem;    /*   8px */
  --space-3:    0.75rem;   /*  12px */
  --space-4:    1rem;      /*  16px */
  --space-5:    1.25rem;   /*  20px */
  --space-6:    1.5rem;    /*  24px */
  --space-8:    2rem;      /*  32px */
  --space-10:   2.5rem;    /*  40px */
  --space-12:   3rem;      /*  48px */
  --space-16:   4rem;      /*  64px */
  --space-20:   5rem;      /*  80px */
  --space-24:   6rem;      /*  96px */
  --space-32:   8rem;      /* 128px */

  /* === LAYOUT === */
  --container-max-width:     1200px;
  --container-padding-x:     var(--space-6);
  --section-padding-y:       var(--space-20);
  --section-padding-y-sm:    var(--space-12);

  /* === BORDES === */
  --border-width-thin:    1px;
  --border-width-base:    2px;
  --border-width-thick:   4px;

  --border-radius-sm:     4px;
  --border-radius-base:   8px;
  --border-radius-md:     12px;
  --border-radius-lg:     16px;
  --border-radius-xl:     24px;
  --border-radius-full:   9999px;

  /* === SOMBRAS === */
  --shadow-sm:   0 1px 3px rgba(0, 0, 0, 0.4);
  --shadow-base: 0 4px 12px rgba(0, 0, 0, 0.5);
  --shadow-md:   0 8px 24px rgba(0, 0, 0, 0.6);
  --shadow-lg:   0 16px 48px rgba(0, 0, 0, 0.7);
  --shadow-glow-brand: 0 0 20px rgba(200, 169, 110, 0.35);  /* Glow dorado */
  --shadow-glow-accent: 0 0 20px rgba(233, 69, 96, 0.4);    /* Glow acento */

  /* === TRANSICIONES === */
  --transition-duration-fast:    150ms;
  --transition-duration-base:    250ms;
  --transition-duration-slow:    400ms;
  --transition-easing-default:   ease-in-out;
  --transition-easing-bounce:    cubic-bezier(0.34, 1.56, 0.64, 1);
  --transition-easing-smooth:    cubic-bezier(0.4, 0, 0.2, 1);

  --transition-base: var(--transition-duration-base) var(--transition-easing-default);
  --transition-fast: var(--transition-duration-fast) var(--transition-easing-default);
  --transition-slow: var(--transition-duration-slow) var(--transition-easing-smooth);

  /* === Z-INDEX === */
  --z-index-below:    -1;
  --z-index-base:      0;
  --z-index-raised:   10;
  --z-index-dropdown: 100;
  --z-index-sticky:   200;
  --z-index-overlay:  300;
  --z-index-modal:    400;
  --z-index-toast:    500;

  /* === COMPONENTES — NAVBAR === */
  --navbar-height:          72px;
  --navbar-bg:              rgba(13, 13, 13, 0.92);
  --navbar-border-bottom:   var(--color-brand-primary);

  /* === COMPONENTES — BOTONES === */
  --btn-padding-y:          var(--space-3);
  --btn-padding-x:          var(--space-8);
  --btn-border-radius:      var(--border-radius-sm);
  --btn-font-weight:        var(--font-weight-bold);
  --btn-letter-spacing:     var(--letter-spacing-wider);
  --btn-transition:         var(--transition-base);

  /* === COMPONENTES — TARJETAS === */
  --card-padding:           var(--space-6);
  --card-border-radius:     var(--border-radius-md);
  --card-border:            var(--border-width-thin) solid rgba(200, 169, 110, 0.2);
  --card-shadow:            var(--shadow-md);

  /* === COMPONENTES — FORMULARIO === */
  --input-padding-y:        var(--space-3);
  --input-padding-x:        var(--space-4);
  --input-border-radius:    var(--border-radius-sm);
  --input-border:           var(--border-width-thin) solid var(--color-neutral-mid);
  --input-border-focus:     var(--border-width-base) solid var(--color-brand-primary);
  --input-bg:               rgba(255, 255, 255, 0.05);
  --input-color:            var(--color-text-primary);
  --input-placeholder-color: var(--color-neutral-mid);

}

@media (prefers-color-scheme: dark) {
  :root {
    /* El sitio ya tiene tema oscuro por defecto.
       Este bloque existe como punto de extensión si en el futuro
       se implementa un tema claro como predeterminado y se necesita
       forzar el oscuro para usuarios con preferencia de sistema. */
    --color-bg-page:         var(--color-brand-secondary);
    --color-bg-section-alt:  var(--color-brand-secondary-alt);
    --color-text-primary:    var(--color-neutral-off-white);
    --color-text-secondary:  var(--color-neutral-mid);
  }
}

@import url('./variables.css');

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 62.5%;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-primary);
  font-size: 1.6rem;
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

img,
video {
  max-width: 100%;
  display: block;
}

a {
  text-decoration: none;
  color: inherit;
}

ul,
ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

.container {
  width: 100%;
  max-width: var(--container-max-width, 1200px); /* TODO: mover a variables.css */
  margin-inline: auto;
  padding-inline: var(--spacing-md);
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  background-color: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  padding-block: var(--spacing-sm);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav__logo {
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: 0.05em;
}

.nav__list {
  display: flex;
  gap: var(--spacing-md);
  align-items: center;
}

.nav__link {
  font-size: 1.4rem;
  font-weight: 500;
  color: var(--color-text);
  transition: color 0.2s ease;
}

.nav__link:hover {
  color: var(--color-primary);
}

.nav__link--active {
  color: var(--color-primary);
  font-weight: 700;
}

.nav__lang-switcher {
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.nav__lang-switcher:hover {
  color: var(--color-primary);
  border-color: var(--color-primary);
}

.footer {
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-block: var(--spacing-lg);
}

.footer__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}

.footer__brand {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: 0.05em;
}

.footer__copy {
  font-size: 1.3rem;
  color: var(--color-text-muted);
}

.footer__nav {
  display: flex;
  gap: var(--spacing-md);
}

.footer__link {
  font-size: 1.3rem;
  color: var(--color-text-muted);
  transition: color 0.2s ease;
}

.footer__link:hover {
  color: var(--color-primary);
}

.page-wrapper {
  padding-top: 6rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.page-wrapper main {
  flex: 1;
}

@media (max-width: 768px) {
  .nav__inner {
    flex-wrap: wrap;
    gap: var(--spacing-sm);
  }

  .nav__list {
    gap: var(--spacing-sm);
    flex-wrap: wrap;
  }

  .footer__inner {
    flex-direction: column;
    align-items: flex-start;
  }

  .footer__nav {
    flex-wrap: wrap;
    gap: var(--spacing-sm);
  }
}

@media (max-width: 480px) {
  .nav__list {
    display: none;
  }

  .nav__list--open {
    display: flex;
    flex-direction: column;
    width: 100%;
    padding-block: var(--spacing-sm);
  }
}

/* ==========================================================================
   sections.css
   Estilos específicos de cada sección de página.
   Depende de: variables.css (custom properties de diseño)
   NO contiene: reset, estilos de header/footer/nav, variables, utilidades genéricas
   ========================================================================== */


/* ==========================================================================
   BLOQUE 1 — Sección #home (Hero)
   ========================================================================== */

section#home {
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  background-image: url('https://picsum.photos/1920/1080');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  overflow: hidden;
}

section#home::before {
  content: '';
  position: absolute;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.55);
  z-index: 1;
}

section#home .hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 720px;
  padding: var(--spacing-lg) var(--spacing-md);
}

section#home .hero-content h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  color: var(--color-text-inverse);
  line-height: 1.15;
  margin-bottom: var(--spacing-sm);
}

section#home .hero-content p {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--color-text-inverse);
  opacity: 0.85;
  margin-bottom: var(--spacing-md);
}


/* ==========================================================================
   BLOQUE 2 — Sección #servicios
   ========================================================================== */

section#servicios {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-bg-secondary);
}

section#servicios .section-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  color: var(--color-text-primary);
}

section#servicios .services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
}

section#servicios .service-card {
  background-color: var(--color-bg-primary);
  border-radius: 8px; /* TODO: tokenizar */
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--spacing-sm);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

section#servicios .service-card:hover {
  transform: translateY(-4px); /* TODO: tokenizar */
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.14);
}

section#servicios .service-card .service-icon {
  width: 48px; /* TODO: tokenizar */
  height: 48px; /* TODO: tokenizar */
  object-fit: contain;
}

section#servicios .service-card h3 {
  font-size: clamp(1.1rem, 2vw, 1.35rem);
  color: var(--color-text-primary);
  margin: 0;
}

section#servicios .service-card p {
  font-size: 0.95rem; /* TODO: tokenizar */
  color: var(--color-text-secondary);
  line-height: 1.6; /* TODO: tokenizar */
  margin: 0;
}


/* ==========================================================================
   BLOQUE 3 — Sección #quienes-somos
   ========================================================================== */

section#quienes-somos {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-bg-primary);
}

section#quienes-somos .section-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  color: var(--color-text-primary);
}

section#quienes-somos .about-layout {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
  align-items: center;
}

section#quienes-somos .about-image {
  width: 100%;
  max-width: 480px; /* TODO: tokenizar */
  border-radius: 8px; /* TODO: tokenizar */
  object-fit: cover;
  aspect-ratio: 4 / 3;
}

section#quienes-somos .about-text {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

section#quienes-somos .about-text p {
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.7; /* TODO: tokenizar */
  margin: 0;
}

section#quienes-somos .team-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
  margin-top: var(--spacing-lg);
}

section#quienes-somos .team-member {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--spacing-sm);
}

section#quienes-somos .team-member img {
  width: 120px; /* TODO: tokenizar */
  height: 120px; /* TODO: tokenizar */
  border-radius: 50%;
  object-fit: cover;
}

section#quienes-somos .team-member h4 {
  font-size: 1.05rem; /* TODO: tokenizar */
  color: var(--color-text-primary);
  margin: 0;
}

section#quienes-somos .team-member span {
  font-size: 0.875rem; /* TODO: tokenizar */
  color: var(--color-text-secondary);
}


/* ==========================================================================
   BLOQUE 4 — Sección #contacto
   ========================================================================== */

section#contacto {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-bg-secondary);
}

section#contacto .section-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  color: var(--color-text-primary);
}

section#contacto .contact-layout {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
  max-width: 860px; /* TODO: tokenizar */
  margin-inline: auto;
}

section#contacto .contact-info {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

section#contacto .contact-info p {
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.6; /* TODO: tokenizar */
  margin: 0;
}

section#contacto .contact-info a {
  color: var(--color-accent);
  text-decoration: none;
}

section#contacto .contact-info a:hover {
  text-decoration: underline;
}

section#contacto .contact-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

section#contacto .contact-form .form-group {
  display: flex;
  flex-direction: column;
  gap: 6px; /* TODO: tokenizar */
}

section#contacto .contact-form label {
  font-size: 0.9rem; /* TODO: tokenizar */
  color: var(--color-text-primary);
  font-weight: 600; /* TODO: tokenizar */
}

section#contacto .contact-form input,
section#contacto .contact-form textarea {
  padding: var(--spacing-sm) var(--spacing-md);
  border: 1px solid var(--color-border); /* TODO: tokenizar border-width */
  border-radius: 6px; /* TODO: tokenizar */
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  font-size: 1rem;
  font-family: var(--font-body);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  width: 100%;
  box-sizing: border-box;
}

section#contacto .contact-form input:focus,
section#contacto .contact-form textarea:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.06); /* TODO: tokenizar — depende del color-accent */
}

section#contacto .contact-form textarea {
  min-height: 140px; /* TODO: tokenizar */
  resize: vertical;
}

section#contacto .contact-form .form-feedback {
  font-size: 0.875rem; /* TODO: tokenizar */
  min-height: 1.25rem; /* TODO: tokenizar */
}

section#contacto .contact-form .form-feedback.success {
  color: var(--color-success);
}

section#contacto .contact-form .form-feedback.error {
  color: var(--color-error);
}


/* ==========================================================================
   BLOQUE 5 — Media Query: Tablet (min-width: 768px)
   ========================================================================== */

@media (min-width: 768px) {

  /* #servicios — grid de 2 columnas en tablet */
  section#servicios .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  /* #quienes-somos — layout horizontal imagen + texto */
  section#quienes-somos .about-layout {
    flex-direction: row;
    align-items: flex-start;
  }

  section#quienes-somos .about-image {
    flex: 0 0 45%;
    max-width: 45%;
  }

  section#quienes-somos .about-text {
    flex: 1;
  }

  /* #quienes-somos — team grid de 2 columnas */
  section#quienes-somos .team-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  /* #contacto — layout horizontal info + formulario */
  section#contacto .contact-layout {
    flex-direction: row;
    align-items: flex-start;
  }

  section#contacto .contact-info {
    flex: 0 0 38%;
  }

  section#contacto .contact-form {
    flex: 1;
  }
}


/* ==========================================================================
   BLOQUE 6 — Media Query: Desktop (min-width: 1200px)
   ========================================================================== */

@media (min-width: 1200px) {

  /* #servicios — grid de 3 columnas en desktop */
  section#servicios .services-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  /* #quienes-somos — team grid de 3 columnas en desktop */
  section#quienes-somos .team-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  /* #home — limitar ancho del hero-content en pantallas muy anchas */
  section#home .hero-content {
    max-width: 860px; /* TODO: tokenizar */
  }
}

